import{_ as a,o as i,c as o,ah as n}from"./chunks/framework.e_ysbW9u.js";const s="/projects/ROSPug/en/latest/assets/image2.BPHbnByf.jpeg",r="/projects/ROSPug/en/latest/assets/image3.6nEoqZj1.png",l="/projects/ROSPug/en/latest/assets/image4.D9zen800.png",p="/projects/ROSPug/en/latest/assets/image5.O3cjqsQp.png",c="/projects/ROSPug/en/latest/assets/image2.B_l1ARwZ.png",h="/projects/ROSPug/en/latest/assets/image2.BfjVCPX_.png",d="/projects/ROSPug/en/latest/assets/image7.DH4xpPsJ.png",g="/projects/ROSPug/en/latest/assets/image8.D-w8DGbQ.png",m="/projects/ROSPug/en/latest/assets/image2.D9XwN4kg.png",u="/projects/ROSPug/en/latest/assets/image3.zGVX-Rhy.png",b="/projects/ROSPug/en/latest/assets/image4.ar9ae7wp.png",A="/projects/ROSPug/en/latest/assets/image5.CKfhraqS.png",f="/projects/ROSPug/en/latest/assets/image2.CSWrcuCc.png",v="/projects/ROSPug/en/latest/assets/image3.BqDXU4nM.png",y="/projects/ROSPug/en/latest/assets/image4.BcaFPldl.png",k="data:image/png;base64,",w="data:image/png;base64,",C="data:image/png;base64,",F="/projects/ROSPug/en/latest/assets/image2.BfjVCPX_.png",_="/projects/ROSPug/en/latest/assets/image6.Bmwoz8fT.png",M="/projects/ROSPug/en/latest/assets/image7.PDwpLJLx.png",q="/projects/ROSPug/en/latest/assets/image8.b2f3pTb9.png",t="/projects/ROSPug/en/latest/assets/image3.zwezjoyW.png",P="/projects/ROSPug/en/latest/assets/image4.DqrrraPd.png",T="/projects/ROSPug/en/latest/assets/image5.Dm6AoR3X.png",x="/projects/ROSPug/en/latest/assets/image8.D-w8DGbQ.png",S="/projects/ROSPug/en/latest/assets/image10.BeCW6PKz.png",L="/projects/ROSPug/en/latest/assets/image11.B-F7-NOc.png",I=JSON.parse('{"title":"9. SLAM Mapping & Autonomous Navigation Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/9.SLAM_Mapping&Autonomous_Navigation_Course.md","filePath":"docs/9.SLAM_Mapping&Autonomous_Navigation_Course.md"}'),B={name:"docs/9.SLAM_Mapping&Autonomous_Navigation_Course.md"};function z(E,e,N,R,j,D){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_9-slam-mapping-autonomous-navigation-course" tabindex="-1">9. SLAM Mapping &amp; Autonomous Navigation Course <a class="header-anchor" href="#_9-slam-mapping-autonomous-navigation-course" aria-label="Permalink to &quot;9. SLAM Mapping &amp; Autonomous Navigation Course&quot;">​</a></h1><p id="anchor_9_1"></p><h2 id="_9-1-slam-mapping-working-principle" tabindex="-1">9.1 SLAM Mapping Working Principle <a class="header-anchor" href="#_9-1-slam-mapping-working-principle" aria-label="Permalink to &quot;9.1 SLAM Mapping Working Principle&quot;">​</a></h2><h3 id="_9-1-1-slam-introduction" tabindex="-1">9.1.1 SLAM Introduction <a class="header-anchor" href="#_9-1-1-slam-introduction" aria-label="Permalink to &quot;9.1.1 SLAM Introduction&quot;">​</a></h3><p>SLAM stands for Simultaneous Localization and Mapping.</p><p>Localization involves determining the pose of a robot in a coordinate system. The origin of orientation of the coordinate system can be obtained from the first keyframe, existing global maps, landmarks, or GPS data.</p><p>Mapping refers to building a map constructed by the surroundings.</p><p>Mapping involves creating a map of the surrounding environment perceived by the robot. The basic geometric elements of the map are points. The main purpose of the map is for localization and navigation. Navigation can be divided into guidance and control. Guidance includes global planning and local planning, while control involves controlling the robot&#39;s motion after the planning is done.</p><h3 id="_9-1-2-slam-mapping-principle" tabindex="-1">9.1.2 SLAM Mapping Principle <a class="header-anchor" href="#_9-1-2-slam-mapping-principle" aria-label="Permalink to &quot;9.1.2 SLAM Mapping Principle&quot;">​</a></h3><img loading="lazy" height="353" width="397" src="'+s+'" class="common_img"><p>SLAM mapping is composed of the following three processes:</p><ul><li><strong>Pre-processing</strong></li></ul><p>Generally, the surrounding environmental information obtained by a Lidar is called &quot;<strong>point cloud</strong>&quot;, which represents a portion of the environment that the robot perceives. The collected object information is presented as a series of scattered data information with exact angles and distances.</p><ul><li><strong>Matching</strong></li></ul><p>The point cloud data of this current local environment is matched by finding the corresponding position on the established map.</p><p>The SLAM system calculates the distance and pose changes of Lidar&#39;s relative motion by matching and comparing point clouds at different moments. This process completes the self-localization of the robot.</p><ul><li><strong>Map fusion</strong></li></ul><p>The new round of data from Lidar is merged into the original map to complete the map update.</p><p>With Lidar as a signal source, pulse laser emitted by the Lidar&#39;s emitter hits the surrounding obstacles, causing scattering. A portion of the light waves reflects back to the Lidar&#39;s receiver, and by utilizing the principle of laser ranging, the distance from the Lidar to the target point can be calculated. By continuously scanning the target object with pulse lasers, data of all target points on the object can be obtained. After performing imaging processing on this data, an accurate three-dimensional image can be generated.</p><h3 id="_9-1-3-mapping-knacks" tabindex="-1">9.1.3 Mapping Knacks <a class="header-anchor" href="#_9-1-3-mapping-knacks" aria-label="Permalink to &quot;9.1.3 Mapping Knacks&quot;">​</a></h3><p>(1) When initializing the mapping process, it&#39;s advisable for the robot to face a straight wall or use a closed cardboard box instead. This allows the Lidar to scan as many points as possible.</p><img loading="lazy" height="423" width="744" src="'+r+'" class="common_img"><p>(2) Strive to move in straight lines to minimize the robot&#39;s rotational movements. Otherwise, the density of feature points in the map may be reduced. When environmental features are weak, position the robot close to the most prominent side of the environment to facilitate mapping.</p><img loading="lazy" height="368" width="350" src="'+l+'" class="common_img"><p>(3) In certain large-environment scenarios, it&#39;s beneficial to allow the robot to complete a closed-loop mapping first, then proceed to scan smaller details in the environment meticulously. For instance, in settings like shopping malls with numerous transparent surfaces and less distinctive features, it&#39;s advantageous to pause the robot at conspicuous environmental features such as pillars, corridors, or inclined walls. Rotate the robot towards these features, allowing the radar to capture them thoroughly. After understanding the characteristic environment, rotate the robot back and resume forward movement. However, avoid stepping backward while rotating whenever possible.</p><img loading="lazy" height="401" width="724" src="'+p+'" class="common_img"><p id="anchor_9_2"></p><h2 id="_9-2-gmapping-mapping" tabindex="-1">9.2 Gmapping Mapping <a class="header-anchor" href="#_9-2-gmapping-mapping" aria-label="Permalink to &quot;9.2 Gmapping Mapping&quot;">​</a></h2><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Please ensure the robot dog has sufficient battery level before mapping. It&#39;s recommended to conduct mapping operations after the robot dog is fully charged.</p></section><h3 id="_9-2-1-gmapping-description" tabindex="-1">9.2.1 Gmapping Description <a class="header-anchor" href="#_9-2-1-gmapping-description" aria-label="Permalink to &quot;9.2.1 Gmapping Description&quot;">​</a></h3><p>There are numerous algorithms for two-dimensional SLAM mapping. Some of the current SLAM algorithms based on the ROS framework include: HectorSLAM, Gmapping, KartoSLAM, CoreSLAM, LagoSLAM, and the more classic Cartographer algorithm.</p><p>The Gmapping algorithm is based on the RBPF particle filter algorithm, which separates the positioning and mapping processes. It first performs positioning and then mapping. This algorithm effectively utilizes odometry information, thereby imposing lower frame rate requirements for Lidar.</p><p>As the scene complexity increases, the number of particles required by the Gmapping algorithm will also increase. Since each particle needs to maintain a map, this can result in excessive computational and memory overheads when constructing a large map. Therefore, the Gmapping algorithm is more suitable for building small-scale maps.</p><h3 id="_9-2-2-gmapping-principle" tabindex="-1">9.2.2 Gmapping Principle <a class="header-anchor" href="#_9-2-2-gmapping-principle" aria-label="Permalink to &quot;9.2.2 Gmapping Principle&quot;">​</a></h3><p>Gmapping algorithm will estimate the Lidar pose firstly based on the previous map and motion model. Then it will compute the weight according to the sensor observation to resample and update the map of particle. It will execute these steps in cycle to complete mapping.</p><img loading="lazy" height="194" width="1214" src="'+c+'" class="common_img"><p>But RBPF particle filter algorithm has defects. It requires ample particles, and resamples frequently. Large amount of particles will result in great computation and storage occupation. And Gmapping has proposed two solutions for these two problems, including improving proposal distribution and selective resampling.</p><h3 id="_9-2-3-enable-lidar-mapping" tabindex="-1">9.2.3 Enable Lidar Mapping <a class="header-anchor" href="#_9-2-3-enable-lidar-mapping" aria-label="Permalink to &quot;9.2.3 Enable Lidar Mapping&quot;">​</a></h3><ul><li><strong>Start Mapping</strong></li></ul><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The input command should be case-sensitive, and keywords can be complemented by pressing the Tab key.</p></section><p>(1) Start the robot, and access the robot system desktop using NoMachine.</p><p>(2) Double click <img loading="lazy" height="59" width="69" src="'+h+'"> to open the command line terminal.</p><p>(3) Execute the command and press Enter to disable app auto-start service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pug_bringup.service</span></span></code></pre></div><p>(4) Open a new command line terminal window, enter the command to start the mapping service, and press Enter. If no error occurs, the mapping service has started successfully.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pug_slam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmapping.launch</span></span></code></pre></div><p>(5) Open a new command-line terminal, then run the command below to start the RVIZ to view the mapping simulation.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pug_slam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rviz_slam.launch</span></span></code></pre></div><img loading="lazy" height="709" width="1265" src="'+d+'" class="common_img"><p>Control the robot to move around to map using the wireless handle.</p><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>Button</strong></th><th style="text-align:center;"><strong>Function</strong></th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td style="text-align:center;">Reset robot&#39;s pose</td></tr><tr><td style="text-align:center;">L1</td><td style="text-align:center;">Look up</td></tr><tr><td style="text-align:center;">L2</td><td style="text-align:center;">Look down</td></tr><tr><td style="text-align:center;">R1</td><td style="text-align:center;">Tilt forward</td></tr><tr><td style="text-align:center;">R2</td><td style="text-align:center;">Tilt backward</td></tr><tr><td style="text-align:center;">↑/ Move left slider forward</td><td style="text-align:center;">Go forward</td></tr><tr><td style="text-align:center;">↓/ Move left slider downward</td><td style="text-align:center;">Go backward</td></tr><tr><td style="text-align:center;">← / Move left slider to left</td><td style="text-align:center;">Turn left</td></tr><tr><td style="text-align:center;">→ / Move left slider to right</td><td style="text-align:center;">Turn right</td></tr><tr><td style="text-align:center;">△ / Move right slider upward</td><td style="text-align:center;">Elevate the robot</td></tr><tr><td style="text-align:center;">× / Move right slider downward</td><td style="text-align:center;">Lower the robot</td></tr><tr><td style="text-align:center;">◻ / Move right slider to left</td><td style="text-align:center;">Speed down (used with the button &quot;<strong>↑</strong>&quot;,&quot;<strong>↓</strong>&quot;)</td></tr><tr><td style="text-align:center;">○ / Move right slider to right</td><td style="text-align:center;">Speed up (used with the button &quot;<strong>↑</strong>&quot;,&quot;<strong>↓</strong>&quot;)</td></tr></tbody></table><ul><li><strong>Save the Map</strong></li></ul><p>(1) Open a new command-line terminal, and input the command to navigate to the folder where the map is saved.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roscd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pug_slam/maps</span></span></code></pre></div><p>(2) Run the following command to save the map.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosrun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> map_server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> map_saver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> map_01</span></span></code></pre></div><p><strong><code>map_01</code></strong> in the command is the map name, which users can rename as needed. If the following message appears, the map has been saved successfully.</p><img loading="lazy" height="96" width="729" src="'+g+'" class="common_img"><p>(3) Use the shortcut key &quot;<strong>Ctrl+C</strong>&quot; in each command line terminal window to terminate the program currently running in the window. After completing the mapping experience, you can initiate the mobile app service via commands or by restarting the robot. If the mobile app service is not activated, the related functions of the app will be inaccessible. (Upon robot restart, the mobile app service will automatically start.)</p><p>To restart the self-starting service of the app, enter the command below and await a single beep from the buzzer to confirm the service startup.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pug_bringup.service</span></span></code></pre></div><h2 id="_9-3-amcl-adaptive-monte-carlo-positioning" tabindex="-1">9.3 AMCL Adaptive Monte Carlo Positioning <a class="header-anchor" href="#_9-3-amcl-adaptive-monte-carlo-positioning" aria-label="Permalink to &quot;9.3 AMCL Adaptive Monte Carlo Positioning&quot;">​</a></h2><h3 id="_9-3-1-amcl-description" tabindex="-1">9.3.1 AMCL Description <a class="header-anchor" href="#_9-3-1-amcl-description" aria-label="Permalink to &quot;9.3.1 AMCL Description&quot;">​</a></h3><p>AMCL (Adaptive Monte Carlo Localization), also known as adaptive Monte Carlo localization, stands as the primary positioning module within the ROS/ROS2 system. As the designated algorithm within the navigation module, it embodies an implementation in ROS/ROS2, leveraging diverse Monte Carlo fusion algorithms.</p><p>AMCL offers a probabilistic positioning system tailored for robots navigating two-dimensional space. Employing particle filters, it adeptly tracks the robot&#39;s pose within a known map.</p><h3 id="_9-3-2-amcl-working-principle" tabindex="-1">9.3.2 AMCL Working Principle <a class="header-anchor" href="#_9-3-2-amcl-working-principle" aria-label="Permalink to &quot;9.3.2 AMCL Working Principle&quot;">​</a></h3><p>The AMCL operates on the principle of utilizing the particle filtering method to approximate the posterior distribution (confidence) of the robot within a known map. This is achieved by employing a set of randomly sampled states (particles), each representing a potential robot pose (position and orientation). These particles are assigned weights based on how effectively the sensor data (e.g., laser scans) aligns with the map.</p><p>Through the resampling process, particles are extracted from the original set with replacement, proportionate to their weights. This eliminates low-weighted particles while bolstering high-weighted ones.</p><p>With multiple iterations, the particle set gradually converges towards the actual robot posture, a phenomenon known as particle convergence. Adaptation occurs through dynamically adjusting the number of particles using the KLD sampling method to match the state space complexity.</p><p>When particle distribution is widely dispersed, increasing particle count enhances exploration capabilities. Conversely, when distribution is concentrated, reducing particle count conserves computing resources. This adaptive approach effectively addresses challenges like robot kidnapping and fixed particle number constraints.</p><img loading="lazy" height="222" width="498" src="'+m+'" class="common_img"><img loading="lazy" height="424" width="690" src="'+u+'" class="common_img"><h3 id="_9-3-3-steps-for-adaptive-monte-carlo-localization-amcl-calculation" tabindex="-1">9.3.3 Steps for Adaptive Monte Carlo Localization (AMCL) Calculation <a class="header-anchor" href="#_9-3-3-steps-for-adaptive-monte-carlo-localization-amcl-calculation" aria-label="Permalink to &quot;9.3.3 Steps for Adaptive Monte Carlo Localization (AMCL) Calculation&quot;">​</a></h3><p>AMCL (Adaptive Monte Carlo Localization) is an algorithm designed for robot positioning, leveraging the Monte Carlo method while incorporating adaptive techniques to enhance accuracy. Here are the general steps of the AMCL algorithm:</p><p>(1) Particle Collection Initialization: Begin by randomly generating a set of particles (also known as hypotheses) within the robot&#39;s environment. Each particle represents a potential pose state of the robot, with the number of particles customizable based on requirements.</p><p>(2) Motion Update: As the robot traverses its environment, update the state of particles to reflect its movement. By accounting for the robot&#39;s motion information, such as velocity and orientation changes, adjust the position and orientation of each particle accordingly. Utilize a motion model to predict the robot&#39;s pose.</p><p>(3) Measurement Update: Robots typically gather environmental data through sensors like lidar scans or visual inputs. Match these measurements with the map to assess the fit of each particle within the observed data. The weight assigned to each particle indicates its alignment with the current environment.</p><p>(4) Resampling: To maintain diversity within the particle collection, perform resampling. This process involves sampling particles based on their weights, favoring those with higher weights while replacing some particles with lower weights. Resampling ensures a balanced representation within the particle set.</p><p>(5) Iterative Update: Continuously repeat steps 2 through 4 until specific convergence criteria are met. Typically, the algorithm terminates when positioning error decreases significantly or when particle weight distribution stabilizes.</p><p>(6) Through these iterative steps, the AMCL algorithm gradually and accurately estimates the robot&#39;s pose within its environment, fulfilling the positioning objective. It&#39;s important to note that the effectiveness of the AMCL algorithm is influenced by parameter selection and the number of particles, necessitating adjustment and optimization according to specific circumstances. AMCL offers improvements over traditional Monte Carlo localization (MCL) methods.</p><h3 id="_9-3-4-description-of-a-simple-mcl-monte-carlo-localization-example" tabindex="-1">9.3.4 Description of a Simple MCL (Monte Carlo Localization) Example: <a class="header-anchor" href="#_9-3-4-description-of-a-simple-mcl-monte-carlo-localization-example" aria-label="Permalink to &quot;9.3.4 Description of a Simple MCL (Monte Carlo Localization) Example:&quot;">​</a></h3><p>(1) Picture a: Initially, the robot is positioned near a door, but its precise location is unknown. We initialize all particles with equal weights.</p><p>(2) Picture b: As the robot senses the presence of a door ahead, particles closer to the door exhibit increased weights.</p><p>(3) Picture c: After resampling and the robot&#39;s movement, particles converge around the original points near the door, depicted as densely black areas in the image.</p><img loading="lazy" height="832" width="1450" src="'+b+'" class="common_img"><p>(4) Picture d: With renewed perception, the robot confirms the presence of the door ahead, further amplifying the weights of particles near the door. Notably, main sampling points shift towards the second door, leading the robot to ascertain its position relative to it.</p><p>(5) Picture e: Following another round of resampling and robot movement, it becomes evident that the robot&#39;s current position lies centrally. Reviewing the example picture provides a tangible sense of particle filtering&#39;s role in localization.</p><img loading="lazy" height="784" width="1519" src="'+A+'" class="common_img"><h2 id="_9-4-ros-robot-autonomous-navigation" tabindex="-1">9.4 ROS Robot Autonomous Navigation <a class="header-anchor" href="#_9-4-ros-robot-autonomous-navigation" aria-label="Permalink to &quot;9.4 ROS Robot Autonomous Navigation&quot;">​</a></h2><h3 id="_9-4-1-autonomous-navigation-description" tabindex="-1">9.4.1 Autonomous Navigation Description <a class="header-anchor" href="#_9-4-1-autonomous-navigation-description" aria-label="Permalink to &quot;9.4.1 Autonomous Navigation Description&quot;">​</a></h3><p>Autonomous navigation, often referred to as self-guided movement, enables a robot to navigate from point A to point B independently. Achieving this capability requires essential components integrated into the robot: a global map, self-positioning system, path planning algorithms, motion control mechanisms, and environmental perception sensors. It&#39;s through the synergy of these components that autonomous navigation becomes feasible. For further details, please consult the accompanying illustrations.</p><img loading="lazy" height="757" width="1611" src="'+f+'" class="common_img"><p>(1) Besides the planner, the navigation module encompasses a <code>cost_map</code>—a raster map containing static obstacle information, delineating passable and impassable areas.</p><p>(2) Concurrently, dynamic obstacle data is transmitted through sensor topics, prompting real-time updates to the <code>cost_map</code> for dynamic obstacle avoidance.</p><p>(3) Beyond mapping, the navigation module relies on positioning information furnished by the <code>amcl</code> module. For alternative positioning modules, simply publish the corresponding topic. Moreover, <code>tf</code> information is imperative, facilitating sensor conversion—a standard practice in robotics.</p><p>(4) Odometry supplies the robot&#39;s pose details, encompassing speed, angle, etc., crucial for the local planner in path planning.</p><p>(5) Ultimately, control commands generated are relayed to the control module via the <code>cmd_vel</code> command, regulating the robot&#39;s movement.</p><h3 id="_9-4-2-key-technologies-for-navigation-implementation" tabindex="-1">9.4.2 Key Technologies for Navigation Implementation <a class="header-anchor" href="#_9-4-2-key-technologies-for-navigation-implementation" aria-label="Permalink to &quot;9.4.2 Key Technologies for Navigation Implementation&quot;">​</a></h3><p>The autonomous navigation principle of ROS robots involves utilizing a suite of function packages and algorithms within ROS to achieve robot positioning, map construction, path planning, and motion control in both known and unknown environments. The ROS navigation module primarily comprises the following components:</p><p>(1) Global map: Provides an overarching view of the robot&#39;s environment. It can utilize SLAM algorithms (e.g., <code>gmapping</code>) to generate a two-dimensional raster map based on odometry and lidar data. Additionally, it can be saved and retrieved using the <code>map_server</code> function package. For insights into SLAM principles, refer to <a href="#anchor_9_1">9.1 SLAM Mapping Working Principle</a> in the same folder.</p><p>(2) Self-positioning: Determines the robot&#39;s position on the map through algorithms. Typically, two algorithms are employed for this purpose: one calculates the current position relative to the origin using odometry, while the other utilizes radar sensors to compare surrounding environment data with map feature points to ascertain the robot&#39;s position.</p><p>(3) Path planning: Facilitates both overall and local path planning based on predefined target points and the global map. Global path planning (e.g., <code>global_planner</code>) employs Dijkstra or A* algorithms to compute the optimal route. Local path planning (e.g., <code>local_planner</code>) utilizes dynamic window techniques to navigate around obstacles and select the most favorable path while adhering to the global plan.</p><p>(4) Motion control: Governs the robot&#39;s speed and direction to adhere to the planned path. The navigation function package can publish messages of type <code>geometry_msgs/Twist</code> via the &quot;<strong>cmd_vel</strong>&quot; topic. These messages, based on the robot&#39;s base coordinate system, transmit motion commands. Therefore, a node subscribing to the &quot;<strong>cmd_vel</strong>&quot; topic is required to convert speed commands into motor commands and transmit them accordingly.</p><p>(5) Environment perception: Enables the perception of surrounding environmental data using sensors such as lidar, cameras, encoders, etc. This data is utilized for map building, localization, <code>cost_map</code> updates, etc. The <code>cost_map</code>, a raster map, contains information on static and dynamic obstacles, delineating passable and impassable areas.</p><h2 id="_9-5-teb-dwa-path-planning" tabindex="-1">9.5 TEB &amp; DWA Path Planning <a class="header-anchor" href="#_9-5-teb-dwa-path-planning" aria-label="Permalink to &quot;9.5 TEB &amp; DWA Path Planning&quot;">​</a></h2><h3 id="_9-5-1-dwa-algorithm" tabindex="-1">9.5.1 DWA Algorithm <a class="header-anchor" href="#_9-5-1-dwa-algorithm" aria-label="Permalink to &quot;9.5.1 DWA Algorithm&quot;">​</a></h3><ul><li><strong>DWA Algorithm Description</strong></li></ul><p>The DWA (Dynamic Window Approach) algorithm operates by sampling various velocity sets (v, w) within the velocity space and forecasting the motion trajectories of these velocities based on the robot&#39;s kinematic model. These trajectories are then evaluated using a scoring function, with the optimal trajectory selected to drive the robot&#39;s movement.</p><p>(1) Advantages:</p><p>① Low computational complexity: Due to speed and acceleration constraints, only safe trajectories are considered, resulting in a small trajectory space.</p><p>② Real-time obstacle avoidance: The algorithm can achieve real-time obstacle avoidance, although the effectiveness may vary.</p><p>③ Suitable for two-wheel differential and omnidirectional mobile models.</p><p>(2) Disadvantages:</p><p>① Limited foresight: The algorithm only simulates and evaluates the next step, which may result in suboptimal obstacle avoidance, especially for complex scenarios.</p><p>② Inadequate dynamic obstacle avoidance: Simulated motion trajectories may be disrupted, leading to poor dynamic obstacle avoidance.</p><p>③ Lack of global optimality: The algorithm selects the next best path rather than the globally optimal path.</p><p>④ Inapplicable to Ackerman models.</p><p>The DWA algorithm transforms the position control of the mobile robot into speed control. When utilizing speed patterns to forecast the robot&#39;s motion trajectory, it is essential to analyze the robot&#39;s motion model. Here, <code>v(t)</code> and <code>w(t)</code> represent the translation speed and angular speed of the robot in the world coordinate system. Within the robot&#39;s sampling period <code>Δt</code>, it moves in a straight line at a constant speed, resulting in small displacements. The robot&#39;s motion model is as follows:</p><img loading="lazy" height="109" width="639" src="'+v+'" class="common_img"><p>In the equation, <code>x(t)</code>, <code>y(t)</code>, and <code>θ(t)</code> represent the robot&#39;s pose in world coordinates at time <code>t</code>.</p><ul><li><strong>Velocity Space and Scoring Function</strong></li></ul><p>The dynamic window method frames the obstacle avoidance challenge as a constrained optimization problem within velocity space. These constraints encompass the non-holonomic constraints of the robot, environmental obstacles, and the dynamic constraints inherent in the robot&#39;s structure.</p><p>Through the design of an evaluation function, the optimal trajectory is discerned within velocity space. During local planning, adherence to the global path, effective obstacle avoidance, and swift progress towards the target are imperative to ascertain the optimal trajectory.</p><p>The evaluation function is defined as follows:</p><img loading="lazy" height="63" width="673" src="'+y+'" class="common_img"><p>The smallest value of <code>G(v, w)</code> yields the best path. Here, <code>k</code> denotes the smoothing function, while <code>α</code>, <code>β</code>, <code>γ</code>, and <code>σ</code> serve as weighting coefficients for each sub-function. The sub-functions are outlined below:</p><p>The &quot;<strong>Heading</strong>&quot; sub-function ensures the robot maintains its orientation towards the endpoint during movement. Lower values of this function correspond to smaller azimuth angles towards the endpoint.</p><p>The &quot;<strong>Goal</strong>&quot; sub-function evaluates the distance between the endpoint of the robot&#39;s local path and the target, continuously minimizing this distance.</p><p>The &quot;<strong>Path</strong>&quot; sub-function assesses the distance from the trajectory&#39;s endpoint to the global path.</p><p>The &quot;<strong>Occ</strong>&quot; sub-function gauges the distance between the robot&#39;s trajectory and obstacles, reflecting its obstacle avoidance capability. If the distance exceeds the robot&#39;s radius, collision risk is low; otherwise, the trajectory is deemed unsafe and discarded.</p><h3 id="_9-5-2-teb-algorithm" tabindex="-1">9.5.2 TEB Algorithm <a class="header-anchor" href="#_9-5-2-teb-algorithm" aria-label="Permalink to &quot;9.5.2 TEB Algorithm&quot;">​</a></h3><ul><li><strong>TEB Algorithm Description</strong></li></ul><p>The TEB (Timed Elastic Band) algorithm enhances motion trajectory by adjusting the initial trajectory from global path planning. Its optimization focuses on minimizing distance to obstacles, path length, and trajectory duration.</p><p>TEB treats path planning as a multi-objective optimization task, aiming to minimize trajectory execution time, maintain a safe distance from obstacles, and adhere to motion dynamics constraints. Since many optimization objectives are local and pertain only to specific continuous states of the robot, the optimization problem entails sparse model optimization.</p><ul><li><strong>TEB Algorithm Realization Procedure</strong></li></ul><p>The enhanced framework for robot control system operates as follows: Global path——&gt;constraints are integrated——&gt;g2o optimization——&gt;speed commands</p><p>(1) Advantage:</p><p>① Suitable for various common car models: including differential, omnidirectional, and Ackerman models.</p><p>② Demonstrates strong foresight: optimizing trajectories in advance.</p><p>③ Exhibits effective dynamic obstacle avoidance: adeptly navigates around dynamic obstacles, and can directly encapsulate obstacle types.</p><p>(2) Disadvantage:</p><p>① High computational complexity: This can be mitigated by sacrificing prediction distance.</p><p>② Significant fluctuations in speed and angle, leading to unstable control: The source code computes speed and angular velocity within the control period based on distance, angle difference, and time difference between two states, resulting in notable fluctuations during control.</p><p>③ Lack of global optimality: Though superior to DWA.</p><ul><li><strong>TEB Model</strong></li></ul><p>The TEB algorithm generates trajectories consisting of N discrete poses with associated time information. These trajectories are then optimized using the General Graph Optimization (G2O) algorithm to minimize path length, minimize time duration, maximize distance from obstacles, and impose constraints on velocity and acceleration, ensuring compliance with robot kinematics requirements.</p><p>The center coordinates and turning direction of a mobile robot jointly determine its pose within the environment. First, define the robot&#39;s pose:</p><img loading="lazy" height="76" width="442" src="'+k+'" class="common_img"><p>Where <code>xi</code>, <code>yi</code>, and <code>βi</code> represent the robot&#39;s position and orientation in the map coordinate system.</p><p>The time interval between two robot poses is defined as <code>ΔTi</code>, recorded in a time sequence:</p><img loading="lazy" height="67" width="477" src="'+w+'" class="common_img"><p>Next, merge the poses and time sequence:</p><img loading="lazy" height="64" width="366" src="'+C+'" class="common_img"><p>The TEB algorithm treats poses and time intervals as optimization variables and, under dynamic constraints, seeks the optimal path. These constraints include velocity and acceleration limits, path length, distance between obstacles and the robot, and the robot&#39;s running time along the trajectory. Subsequently, the optimal path <code>Q</code> is obtained by setting a weighted multi-objective function.</p><h2 id="_9-6-lidar-multi-point-navigation-obstacle-avoidance" tabindex="-1">9.6 Lidar Multi-Point Navigation &amp; Obstacle Avoidance <a class="header-anchor" href="#_9-6-lidar-multi-point-navigation-obstacle-avoidance" aria-label="Permalink to &quot;9.6 Lidar Multi-Point Navigation &amp; Obstacle Avoidance&quot;">​</a></h2><p>If you need to know more details about the map construction, please refer to the file locating in <a href="#anchor_9_2">9.2 Gmapping Mapping</a>.</p><h3 id="_9-6-1-navigation-configuration" tabindex="-1">9.6.1 Navigation Configuration <a class="header-anchor" href="#_9-6-1-navigation-configuration" aria-label="Permalink to &quot;9.6.1 Navigation Configuration&quot;">​</a></h3><p>(1) Start the robot dog, and access the robot system desktop using NoMachine.</p><p>(2) Double-click <img loading="lazy" height="59" width="69" src="'+F+'"> to open the command-line terminal.</p><p>(3) Execute the command to terminate the app auto-start service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pug_bringup.service</span></span></code></pre></div><p>(4) Open a new command-line terminal, and run the command below to enable the navigation service. If there is no error reported, it means that the navigation service is enabled successfully.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pug_navigation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> navigation.launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> map:=map_01</span></span></code></pre></div><p>(5) Open a new command-line terminal and enter the command below to launch the RViz model for viewing the navigation simulation.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pug_navigation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rviz_navigation.launch</span></span></code></pre></div><img loading="lazy" height="774" width="1259" src="'+_+'" class="common_img"><h3 id="_9-6-2-start-navigation" tabindex="-1">9.6.2 Start Navigation <a class="header-anchor" href="#_9-6-2-start-navigation" aria-label="Permalink to &quot;9.6.2 Start Navigation&quot;">​</a></h3><p>The functions of the tools are as follows:</p><p>(1) 2D pose estimation: Sets the initial position of the robot dog.</p><p>(2) 2D Nav Goal: Sets the target point for navigation.</p><p>(3) Publish point: Publishes multiple target points. The robot dog will automatically plan a path to reach each target point while avoiding obstacles.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If you need to terminate the navigation, click on &#39;<strong>2D Nav Goal</strong>&#39;. If the robot dog&#39;s position is changed due to external force, you need to reset the robot dog&#39;s position.</p></section><img loading="lazy" height="255" width="519" src="'+M+'" class="common_img"><p>After setting the target points, two paths will be generated. The red line represents the direct distance between the robot dog and the target, while the green line depicts the path planned by the robot dog.</p><img loading="lazy" height="780" width="1255" src="'+q+'" class="common_img"><h2 id="_9-7-app-mapping-navigation" tabindex="-1">9.7 App Mapping &amp; Navigation <a class="header-anchor" href="#_9-7-app-mapping-navigation" aria-label="Permalink to &quot;9.7 App Mapping &amp; Navigation&quot;">​</a></h2><h3 id="_9-7-1-preparation" tabindex="-1">9.7.1 Preparation <a class="header-anchor" href="#_9-7-1-preparation" aria-label="Permalink to &quot;9.7.1 Preparation&quot;">​</a></h3><p>You can control the robot dog and monitor its mapping progress using your phone. Additionally, you can set navigation target points for the robot dog.</p><p>(1) The &quot;<strong>Make A APP</strong>&quot; app is for mapping, and &quot;<strong>Map Nav</strong>&quot; is for navigation.</p><p>(2) Both apps are compatible only with Android systems. You can find the software installation package in the same directory, which you can then transfer to your phone for installation.</p><h3 id="_9-7-2-mapping" tabindex="-1">9.7.2 Mapping <a class="header-anchor" href="#_9-7-2-mapping" aria-label="Permalink to &quot;9.7.2 Mapping&quot;">​</a></h3><ul><li><strong>App Mapping</strong></li></ul><p>(1) Start the robot dog, and access the robot system desktop using NoMachine.</p><p>(2) Start SLAM mapping. To access the detailed instructions, please refer to the file saved in <a href="#anchor_9_2">9.2 Gmapping Mapping</a>.</p><p>(3) Run the following command to initiate the app mapping service.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pug_slam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmapping.launch</span></span></code></pre></div><p>(4) Connect to the WiFi generated by the robot dog starting with <strong>HW</strong>.</p><img loading="lazy" height="854" width="616" src="'+t+'" class="common_img" style="width:400px;"><p>(5) Open the &quot;<strong>Make A Map</strong>&quot; app, and change the &quot;<strong>Master URI</strong>&quot; field to <a href="http://192.168.149.1:11311" target="_blank" rel="noreferrer">http://192.168.149.1:11311</a>, then click on &quot;<strong>CONNECT</strong>&quot; button.</p><img loading="lazy" height="281" width="379" src="'+P+'" class="common_img"><p>The app interface is divided into two zones. The map is displayed on the yellow frame, and the blue frame section is for controlling the robot.</p><img loading="lazy" height="630" width="1267" src="'+T+'" class="common_img"><ul><li><strong>Save the Map</strong></li></ul><p>(1) Open a new command line terminal window, enter the following command, and press Enter to navigate to the folder where maps are stored:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roscd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pug_slam/maps</span></span></code></pre></div><p>(2) Run the command below to save the map.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosrun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> map_server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> map_saver</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> map_01</span></span></code></pre></div><p><strong><code>map_01</code></strong> in the command is the map name, which can be renamed according to your needs. If the following message appears, the map has been saved successfully.</p><img loading="lazy" height="96" width="729" src="'+x+'" class="common_img"><h3 id="_9-7-3-navigation" tabindex="-1">9.7.3 Navigation <a class="header-anchor" href="#_9-7-3-navigation" aria-label="Permalink to &quot;9.7.3 Navigation&quot;">​</a></h3><ul><li><strong>APP Navigation</strong></li></ul><p>(1) Start the robot dog, and access the robot system desktop using NoMachine.</p><p>(2) Enter the following command to initiate the navigation service. If there is no error reported, it means that the navigation service is enabled successfully.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pug_navigation</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> navigation.launch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> map:=map_01</span></span></code></pre></div><p>(3) Connect your phone to the WiFi starting with <strong>HW</strong>. The initial password is <strong>hiwonder</strong>.</p><img loading="lazy" height="854" width="616" src="'+t+'" class="common_img" style="width:400px;"><p>(4) Open &quot;<strong>Map Nav</strong>&quot; app, and input <code>http://192.168.149.1:11311</code> in &quot;<strong>Master URI</strong>&quot; bar, then click &quot;<strong>CONNECT</strong>&quot;.</p><img loading="lazy" height="552" width="693" src="'+S+'" class="common_img" style="width:400px;"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>The icon &#39;<strong>CHOOSE A MAP</strong>&#39; serves no practical purpose. Map will be loaded automatically.</p></section><p>The &quot;<strong>Map Nav</strong>&quot; interface is divided into three sections. The green box displays the map; the red box controls the robot dog&#39;s movement; and the options &#39;<strong>Set Pose</strong>&#39; and &#39;<strong>Set Goal</strong>&#39; in the blue box, used together with the green box, are for setting the robot dog&#39;s initial position and navigation target.</p><img loading="lazy" height="636" width="1265" src="'+L+'" class="common_img"><p>(1) Select &quot;<strong>Set Pose</strong>&quot;, then press one point on the map to set it as the initial position of robot.</p><p>(2) Drag arrow in red section to control ROSPug to move so as to calibrate the position.</p><p>(3) Select &quot;<strong>Set Goal</strong>&quot;, then press one point on the map to set it as the destination.</p><p>(4) After initial position and destination are set, the path between these two points is generated automatically. Then robot will move from the initial position to the set destination.</p>',215)])])}const W=a(B,[["render",z]]);export{I as __pageData,W as default};
